package br.com.marquesautodetail.api.avaliacao; import br.com.marquesautodetail.api.agendamento.Agendamento; import br.com.marquesautodetail.api.empresa.Empresa; import br.com.marquesautodetail.api.usuario.Usuario; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="avaliacoes") public class Avaliacao{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Integer nota; @Column(length=1000) private String comentario; private LocalDateTime criadoEm=LocalDateTime.now(); @ManyToOne private Usuario cliente; @ManyToOne private Empresa empresa; @OneToOne private Agendamento agendamento; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Integer getNota(){return nota;} public void setNota(Integer nota){this.nota=nota;} public String getComentario(){return comentario;} public void setComentario(String comentario){this.comentario=comentario;} public LocalDateTime getCriadoEm(){return criadoEm;} public void setCriadoEm(LocalDateTime criadoEm){this.criadoEm=criadoEm;} public Usuario getCliente(){return cliente;} public void setCliente(Usuario cliente){this.cliente=cliente;} public Empresa getEmpresa(){return empresa;} public void setEmpresa(Empresa empresa){this.empresa=empresa;} public Agendamento getAgendamento(){return agendamento;} public void setAgendamento(Agendamento agendamento){this.agendamento=agendamento;} }
